package au.com.parristech.joshrs.android.protocol

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test

/**
 * Byte-exact cross-implementation vectors.
 *
 * Generated by the verified Python probe against the pinned engine's key pair:
 *
 * ```
 * PLAIN_HEX=0a112233445566778831415926271828180000303970726f6265757365720a70726f6265706173730a
 * ENC_HEX=59f8ffa8a99236bf5bf9b02b5e76799034aa3def6f3900042e8fe1719d87d89f...
 * ```
 *
 * Revision-377 RSA has no padding, so the ciphertext is deterministic: if these match,
 * the Kotlin block is byte-identical to one the live server accepted (status 2).
 */
class LoginBlock377Test {

    private fun hex(s: String) = ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
    private fun toHex(b: ByteArray) = b.joinToString("") { "%02x".format(it.toInt() and 0xff) }

    // The pinned engine's public key. NOTE: its data/config/public.pem has modulus and
    // exponent swapped; these are the corrected values taken from the key pair.
    private val modulus = hex(
        "88c38748a58228f7261cdc340b5691d7d0975dee0ecdb717609e6bf971eb3fe7" +
            "23ef9d130e4686813739768ad9472eb46d8bfcc042c1a5fcb05e931f632eea5d"
    )
    private val exponent = hex("81f390b2cf8ca7039ee507975951d5a0b15a87bf8b3f99c966834118c50fd94d")
    private val seeds = intArrayOf(0x11223344, 0x55667788, 0x31415926, 0x27182818)

    @Test
    fun `plaintext layout matches the verified reference`() {
        val plain = LoginBlock377.buildPlaintext(seeds, 12345, "probeuser", "probepass")
        assertEquals(
            "0a112233445566778831415926271828180000303970726f6265757365720a70726f6265706173730a",
            toHex(plain)
        )
        assertEquals(41, plain.size)
        assertEquals(LoginBlock377.MARKER, plain[0].toInt() and 0xff)
    }

    @Test
    fun `credentials are terminated with 0x0A not NUL`() {
        val plain = LoginBlock377.buildPlaintext(seeds, 1, "bob", "pw")
        assertEquals(0x0a, plain[1 + 16 + 4 + 3].toInt() and 0xff)
        assertEquals(0x0a, plain[plain.size - 1].toInt() and 0xff)
    }

    @Test
    fun `rsa ciphertext is byte-identical to the accepted reference`() {
        val plain = LoginBlock377.buildPlaintext(seeds, 12345, "probeuser", "probepass")
        val enc = LoginBlock377.rsaEncrypt(plain, modulus, exponent)
        assertEquals(64, enc.size)
        assertEquals(
            "59f8ffa8a99236bf5bf9b02b5e76799034aa3def6f3900042e8fe1719d87d89f" +
                "a0b771702d958671b1e588fd2ff97e3eed90187094c458a219b41a2806dc885e",
            toHex(enc)
        )
    }

    @Test
    fun `decrypt cipher is seeded with each seed plus 50`() {
        val a = LoginBlock377.decryptCipher(seeds)
        val b = IsaacCipher(intArrayOf(seeds[0] + 50, seeds[1] + 50, seeds[2] + 50, seeds[3] + 50))
        repeat(8) { assertEquals(b.nextInt(), a.nextInt()) }
    }

    @Test
    fun `login frame uses the revision escape because 377 exceeds one byte`() {
        val crcs = ByteArray(36) { it.toByte() }
        val rsa = ByteArray(64) { 0x5a }
        val frame = LoginBlock377.buildLoginFrame(crcs, rsa)

        assertEquals(LoginBlock377.LOGIN_OPCODE, frame[0].toInt() and 0xff)
        assertEquals(frame.size - 2, frame[1].toInt() and 0xff)
        assertEquals(0xff, frame[2].toInt() and 0xff)
        assertEquals(377, ((frame[3].toInt() and 0xff) shl 8) or (frame[4].toInt() and 0xff))
        assertEquals(0, frame[5].toInt() and 0xff) // info
        assertArrayEquals(crcs, frame.copyOfRange(6, 42))
        assertEquals(64, frame[42].toInt() and 0xff)
        assertEquals(107, frame.size)
    }

    @Test
    fun `login frame rejects a wrong number of crc bytes`() {
        assertThrows(IllegalArgumentException::class.java) {
            LoginBlock377.buildLoginFrame(ByteArray(35), ByteArray(64))
        }
    }

    @Test
    fun `rsa rejects a block that does not fit the modulus`() {
        val tooBig = ByteArray(64) { 0xff.toByte() }
        assertThrows(IllegalArgumentException::class.java) {
            LoginBlock377.rsaEncrypt(tooBig, modulus, exponent)
        }
    }

    @Test
    fun `response splits into status, two byte preamble and isaac frames`() {
        val response = byteArrayOf(2, 0x01, 0x02) + ByteArray(10) { 0x7f }
        val split = LoginBlock377.splitResponse(response)
        assertEquals(2, split.status)
        assertArrayEquals(byteArrayOf(0x01, 0x02), split.preamble)
        assertEquals(10, split.frames.size)
    }
}
